'use strict';

// MODULES //

var isnan = require( '@stdlib/math-base-assert-is-nan' );
var incrmmeanvar = require( '@stdlib/stats-incr-mmeanvar' );


// MAIN //

/**
* Returns an accumulator function which incrementally computes a moving arithmetic mean and unbiased sample variance, ignoring `NaN` values.
*
* @param {Collection} [out] - output array
* @param {PositiveInteger} window - window size
* @throws {TypeError} output argument must be array-like
* @throws {TypeError} window size must be a positive integer
* @returns {Function} accumulator function
*
* @example
* var accumulator = incrnanmmeanvar( 3 );
*
* var v = accumulator();
* // returns null
*
* v = accumulator( 2.0 );
* // returns [ 2.0, 0.0 ]
*
* v = accumulator( NaN );
* // returns [ 2.0, 0.0 ]
*
* v = accumulator( -5.0 );
* // returns [ -1.5, 24.5 ]
*
* v = accumulator( 3.0 );
* // returns [ 0.0, 19.0 ]
*
* v = accumulator();
* // returns [ 0.0, 19.0 ]
*/
function incrnanmmeanvar( out, window ) {
	var mmeanvar;
	if ( arguments.length > 1 ) {
		mmeanvar = incrmmeanvar( out, window );
	} else {
		mmeanvar = incrmmeanvar( out );
	}
	return accumulator;

	/**
	* If provided a value, the accumulator function returns updated accumulated values. If provided `NaN` or no value, the accumulator function returns the current accumulated values.
	*
	* @private
	* @param {number} [x] - input value
	* @returns {(ArrayLikeObject|null)} output array or null
	*/
	function accumulator( x ) {
		if ( arguments.length === 0 || isnan( x ) ) {
			return mmeanvar();
		}
		return mmeanvar( x );
	}
}


// EXPORTS //

module.exports = incrnanmmeanvar;
